import {
  memo,
  Suspense,
  useCallback,
  use,
  useState,
  useEffect,
  useRef,
  useMemo,
} from 'react'
import cx from 'classnames'

import { darkMode, lightMode } from './index.css'
import { easy, medium, hard, gameState, game, menuButton } from './App.css'

import { default as Settings, getFallback } from './Settings'

import Help from './Help'
import Debug from './Debug'
import TabList from './TabList'
import { HighScoresForm, HighScoresView } from './HighScores'

import Card from './Card'
import Dialog from './Dialog'
import { DataContext } from './DataProvider'

// minstd_rand
// this is a pseudo-random number generator that needs an initial seed
// not sure how or why it works, but it seems to.
// both range & id need to be deterministic for it to work (because all the tiles are sorted by random id)
const rnd = (s) => {
  const _rnd = () => ((2 ** 31 - 1) & (s = Math.imul(48271, s))) / 2 ** 31
  _rnd() // first call is always junk
  return {
    range(min, max) {
      return Math.floor(_rnd() * max) + min
    },
    id() {
      return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'
        .replace(/x/g, () => Math.floor(_rnd() * 16).toString(16))
        .replace(/y/g, () => Math.floor(8 + _rnd() * 4).toString(16))
    },
  }
}

const defaultNoMotion = () =>
  window.matchMedia('(prefers-reduced-motion: reduce)').matches

const Loading = () => <>Loading!!</>

function App() {
  const { tilesets, difficulties, reducedMotionOptions } = use(DataContext)
  const [seed, setSeed] = useState(() => Math.floor(Math.random() * 500))
  const [score, setScore] = useState('')
  const [debugMode, setDebugMode] = useState(false)

  const flippedCountRef = useRef(0)
  const mainMenuDialogRef = useRef(null)
  const victoryDialogRef = useRef(null)

  const tilesRef = useRef(new Map())
  const selectionRef = useRef(null)

  const [difficultyKey, setDifficultyKey] = useState(() =>
    getFallback('difficulty', difficulties),
  )

  const [tilesetKey, setTilesetKey] = useState(() =>
    getFallback('tileset', tilesets),
  )

  const [noMotion, setNoMotion] = useState(() =>
    getFallback('reduced_motion', reducedMotionOptions, defaultNoMotion),
  )

  const difficultyValue = difficulties[difficultyKey]

  useEffect(() => {
    function handleKeyDown(e) {
      if (victoryDialogRef.current.open) return // don't do this if the other dialog is open
      if (e.key === 'Escape' && !mainMenuDialogRef.current.open) {
        mainMenuDialogRef.current.showModal()
        e.preventDefault()
      }
    }

    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [])

  const reset = useCallback((reseed = false) => {
    flippedCountRef.current = 0
    if (reseed) setSeed(Math.floor(Math.random() * 500))
    setScore('')
  }, [])

  const tiles = useMemo(() => {
    const random = rnd(seed)
    const TOTAL_TILES = parseInt(difficultyValue, 10)
    const emojis = new Map()

    if (tilesets[tilesetKey].length < TOTAL_TILES) {
      throw new Error('no emoji')
    }

    while (emojis.size < TOTAL_TILES) {
      const index = random.range(0, tilesets[tilesetKey].length - 1)
      const entry = tilesets[tilesetKey][index]
      emojis.set(entry.emoji, entry.label)
    }

    return Array.from(emojis.keys())
      .flatMap((emoji) => [emoji, emoji])
      .map((emoji) => {
        const id = random.id()
        return {
          emoji,
          label: emojis.get(emoji),
          id,
          handleRef(node) {
            if (node) tilesRef.current.set(id, node)
            return () => tilesRef.current.delete(id)
          },
          handleReveal() {
            if (selectionRef.current == null) {
              selectionRef.current = { id, emoji }
            } else if (selectionRef.current.emoji === emoji) {
              return Promise.all([
                tilesRef.current.get(id).success(),
                tilesRef.current.get(selectionRef.current.id).success(),
              ]).then((failures) => {
                selectionRef.current = null
                setScore((prev) =>
                  failures.reduce(
                    (total, item) => total + item,
                    prev === '' ? 0 : prev,
                  ),
                )
                if (tiles.length / 2 === ++flippedCountRef.current) {
                  victoryDialogRef.current.showModal()
                }
              })
            } else {
              tilesRef.current.get(id).fail()
              tilesRef.current.get(selectionRef.current.id).fail()
              selectionRef.current = null
            }
          },
        }
      })
      .sort((a, b) => a.id.localeCompare(b.id))
  }, [tilesets, tilesetKey, difficultyValue, seed])

  return (
    <>
      <header>
        <h1>Memory</h1>
        <dl className={gameState}>
          <dt>version</dt>
          <dd>{window.APP_VERSION}</dd>
          <dt>game id</dt>
          <dd>{seed}</dd>
          <dt>difficulty</dt>
          <dd>{difficultyKey}</dd>
          <dt>tileset</dt>
          <dd>{tilesetKey}</dd>
          {score !== '' && (
            <>
              <dt>score</dt>
              <dd>{score}</dd>
            </>
          )}
        </dl>
        <button
          className={menuButton}
          onClick={() => mainMenuDialogRef.current.showModal()}
          aria-label="Settings Menu / New Game / Etc"
        >
          ⋮
        </button>
      </header>

      <main
        className={cx(game, {
          [easy]: difficultyValue === difficulties.easy,
          [medium]: difficultyValue === difficulties.medium,
          [hard]: difficultyValue === difficulties.hard,
        })}
      >
        {tiles.map(({ id, emoji, label, handleRef, handleReveal }) => (
          <Card
            key={id}
            id={id}
            data-emoji={emoji}
            data-label={label}
            ref={handleRef}
            onReveal={handleReveal}
            noMotion={noMotion}
          />
        ))}
      </main>

      <Dialog ref={mainMenuDialogRef}>
        <TabList
          entries={[
            {
              id: 'settings',
              label: 'settings',
              panel: (
                <Settings
                  seed={seed}
                  onSettingChange={(key, value) => {
                    if (key === 'theme') {
                      document.body.classList.remove(darkMode, lightMode)
                      if (value != null) {
                        document.body.classList.add(
                          value === 'DARK' ? darkMode : lightMode,
                        )
                      }
                      return
                    }
                    if (key === 'difficulty') setDifficultyKey(value)
                    if (key === 'tileset') setTilesetKey(value)
                    if (key === 'seed') setSeed(value)
                    if (key === 'reduced_motion')
                      setNoMotion(
                        value == null
                          ? defaultNoMotion()
                          : value === 'reduced_motion'
                            ? true
                            : false,
                      )
                    reset(false)
                  }}
                />
              ),
            },
            {
              id: 'help',
              label: 'help',
              panel: <Help />,
            },
            {
              id: 'high-scores',
              label: 'high scores',
              panel: (
                <Suspense fallback={<Loading />}>
                  <HighScoresView
                    difficulty={difficultyKey}
                    tileset={tilesetKey}
                  />
                </Suspense>
              ),
            },
            debugMode && {
              id: 'debug',
              label: 'debug',
              panel: <Debug />,
            },
          ].filter(Boolean)}
        />
        <p>Memory {window.APP_VERSION}</p>
        <p>
          <a
            rel="noreferrer noopener"
            target="_blank"
            href="https://github.com/tswaters/memory"
          >
            Fork me on GitHub!
          </a>
        </p>
        <button
          style={{
            position: 'fixed',
            right: '5px',
            bottom: '5px',
            border: 0,
            backgroundColor: 'transparent',
            textShadow: '1px 1px 2px var(--background-color)',
          }}
          onClick={() => setDebugMode(true)}
        >
          π
        </button>
      </Dialog>

      <Dialog ref={victoryDialogRef} onClose={reset}>
        <h2>You win!</h2>
        <p>
          You scored {score} on seed #{seed} and difficulty {difficultyKey}
        </p>
        <hr />
        <HighScoresForm
          seed={seed}
          tileset={tilesetKey}
          difficulty={difficultyKey}
          score={score}
          onSubmitNewScore={() => setScore('')}
        />
        <Suspense fallback={<Loading />}>
          <HighScoresView
            tileset={tilesetKey}
            difficulty={difficultyKey}
            seed={seed}
          />
        </Suspense>
      </Dialog>
    </>
  )
}

export default memo(App)
